(function () {
    var panel = $.GetContextPanel();
    var segmentsContainer = panel.FindChildTraverse("SegmentsContainer");
    var multiplierLabel = panel.FindChildTraverse("MultiplierLabel");
    var fills = [];
    var currentCount = 0;

    function rebuildSegments(count) {
        if (!segmentsContainer) {
            return;
        }
        segmentsContainer.RemoveAndDeleteChildren();
        fills = [];
        currentCount = count;
        for (var i = 0; i < count; i++) {
            var segment = $.CreatePanel("Panel", segmentsContainer, "BossSegment" + i);
            segment.hittest = false;
            segment.style.width = "16px";
            segment.style.height = "36px";
            segment.style.backgroundColor = "rgba(255, 255, 255, 0.2)";
            segment.style.border = "1px solid rgba(255, 255, 255, 0.5)";
            segment.style.borderRadius = "4px";
            segment.style.layoutOverflow = "hidden";

            var fill = $.CreatePanel("Panel", segment, "BossSegmentFill" + i);
            fill.hittest = false;
            fill.style.height = "100%";
            fill.style.backgroundColor = "#F44336";
            fill.style.width = "0%";
            fill.style.transition = "width 0.1s linear";

            fills.push(fill);
        }
    }

    function updateSegments(data) {
        if (!data) {
            return;
        }

        var segmentCount = Math.max(1, data.segments || 1);
        if (segmentCount !== currentCount) {
            rebuildSegments(segmentCount);
        }

        var segmentValue = data.segment_value || 10000;
        var currentHealth = Math.max(0, Math.min(data.current_health || 0, data.max_health || 0));
        var remaining = currentHealth;

        for (var i = 0; i < fills.length; i++) {
            var fillPanel = fills[i];
            if (!fillPanel) {
                continue;
            }

            var fillRatio = 0;
            if (segmentValue > 0) {
                fillRatio = Math.min(1, Math.max(0, remaining / segmentValue));
            }
            fillPanel.style.width = (fillRatio * 100) + "%";
            remaining -= segmentValue;
            if (remaining < 0) {
                remaining = 0;
            }
        }

        if (multiplierLabel) {
            multiplierLabel.text = "×" + (data.multiplier || segmentCount);
        }
    }

    function tick() {
        updateSegments(panel.Data);
        $.Schedule(0.1, tick);
    }

    tick();
})();
"@"}

